# WAR ARENA - Mini App (promo banner + daily-limit + membership gate, English) - Installer
# Writes the 3 Mini App files into miniapp/ in the project root.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-miniapp.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Mini App installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "miniapp/index.html" ""
Write-B64 "miniapp/terms.html" ""
Write-B64 "miniapp/privacy.html" ""

Write-Host ""; Write-Host "Mini App installed into miniapp/ (promo + daily-limit + membership UI)." -ForegroundColor Green
Write-Host "Open miniapp/index.html to preview (demo mode). Set API_BASE for live states." -ForegroundColor Yellow
